"""Strict JSON driver for full-width forwarding compilation and image planning."""
import json
import sys
import native
from protocol import Invalid, MAX_INPUT, parse_request

U = 1 << 128


def changes(before, after):
    """Merge two canonical atlases, coalescing by the ordered hop pair."""
    a, ah = before
    b, bh = after
    i = j = pos = 0
    out = []
    while pos < U:
        ae = a[i + 1] if i + 1 < len(a) else U
        be = b[j + 1] if j + 1 < len(b) else U
        end = min(ae, be)
        old, new = ah[i], bh[j]
        if old != new:
            if out and out[-1][1] == pos and out[-1][2:] == [old, new]:
                out[-1][1] = end
            else:
                out.append([pos, end, old, new])
        pos = end
        if end == ae:
            i += 1
        if end == be:
            j += 1
    return [[f'{start:032x}', f'{end:032x}', old, new]
            for start, end, old, new in out]


def compile_request(cases):
    # First compile and validate ALL committed atlases. In particular, no
    # optimizer is invoked until the forwarding-run domain checks succeed.
    histories = []
    total_runs = 0
    for case in cases:
        routes = dict(case['initial'])
        versions = []

        def publish():
            nonlocal total_runs
            starts, hops = native.atlas(routes)
            total_runs += len(starts)
            if len(starts) > 64 or total_runs > 128:
                raise Invalid('forwarding-run budget')
            versions.append((starts, hops))

        publish()
        for tx in case['transactions']:
            for op, route, hop in tx:
                if op == 'set':
                    routes[route] = hop
                else:
                    routes.pop(route, None)
            publish()
        histories.append(versions)

    results = []
    for case, versions in zip(cases, histories):
        objective, images, answers = native.optimize(
            versions, case['bursts'], case['cache_pages'], case['costs'])
        results.append({
            'versions': [{'starts': [f'{x:032x}' for x in starts],
                          'hops': hops, 'image': image}
                         for (starts, hops), image in zip(versions, images)],
            'changes': [changes(versions[i], versions[i + 1])
                        for i in range(len(versions) - 1)],
            'bursts': answers,
            'objective': objective,
        })
    return {'cases': results}


def main():
    try:
        cases = parse_request(sys.stdin.buffer.read(MAX_INPUT + 1))
        result = compile_request(cases)
    except Invalid:
        result = {'error': 'invalid'}
    json.dump(result, sys.stdout, separators=(',', ':'), allow_nan=False)
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
